from datetime import datetime
def task_func(json_data):
    try:
        data = json.loads(json_data)
        utc_datetime = data.get('utc_datetime', '')
        if not utc_datetime:
            return False
        date_obj = datetime.strptime(utc_datetime, '%Y-%m-%dT%H:%M:%S')
        return date_obj.weekday() in [5, 6]
