import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}

    url_pattern = r'https?://[^\s"]+'
    urls = re.findall(url_pattern, json.dumps(data))
    url_counts = dict(Counter(urls))

    return dict(sorted(url_counts.items(), key=lambda x: x[1], reverse=True)[:top_n])

