import json
import re
import pandas as pd
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    def normalize_value(value):
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, str) and re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) * 2
        elif isinstance(value, list):
            return [normalize_value(v) for v in value]
        return value

    normalized_data = {k: normalize_value(v) for k, v in data.items()}
    return pd.DataFrame([normalized_data])

import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    with open(input_file, "r") as f:
        data = json.load(f)

    stats = defaultdict(list)
    for d in data:
        for key, value in d.items():
            if isinstance(value, (int, float)):
                stats[key].append(value)

    result = {k: {"mean": np.mean(v), "median": np.median(v)} for k, v in stats.items()}
    df = pd.DataFrame(result).T.sort_index()
    df.columns = ['mean', 'median']
    return df

